package com.yuegang.zhihui.training.api;import com.yuegang.zhihui.common.core.ApiResponse;import com.yuegang.zhihui.common.web.TraceIdResolver;import com.yuegang.zhihui.training.application.LearningPathService;import com.yuegang.zhihui.training.security.TrainingUserResolver;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import java.util.List;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/training/paths")public final class LearningPathController{private final LearningPathService service;private final TrainingUserResolver users;public LearningPathController(LearningPathService s,TrainingUserResolver u){service=s;users=u;}@GetMapping ApiResponse<List<LearningPathView>>paths(@RequestParam String positionCode,HttpServletRequest r){users.resolve(r);return ok(service.byPosition(positionCode),r);}@GetMapping("/admin/all")ApiResponse<List<LearningPathView>>all(HttpServletRequest r){users.requirePermission(r,"training:course:write");return ok(service.all(),r);}@PostMapping("/admin")ApiResponse<LearningPathView>create(@Valid @RequestBody SaveLearningPathRequest b,HttpServletRequest r){users.requirePermission(r,"training:course:write");return ok(service.create(b),r);}@PutMapping("/admin/{id}/courses")ApiResponse<LearningPathView>course(@PathVariable String id,@Valid @RequestBody AddPathCourseRequest b,HttpServletRequest r){users.requirePermission(r,"training:course:write");return ok(service.addCourse(id,b),r);}private static<T>ApiResponse<T>ok(T x,HttpServletRequest r){return ApiResponse.success(x,TraceIdResolver.resolve(r));}}
